dashboard.definition:
{
  "title": "Cache Performance",
  "description": "Prompt-cache effectiveness and model-aware savings",
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "inputs": {
    "input_timerange": {
      "type": "input.timerange",
      "options": {
        "token": "global_time",
        "defaultValue": "-7d@d,now"
      },
      "title": "Time Range"
    },
    "input_model": {
      "type": "input.dropdown",
      "title": "Model",
      "dataSources": {
        "primary": "ds_model_options"
      },
      "options": {
        "defaultValue": "*",
        "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
        "token": "model_tok"
      },
      "context": {
        "formattedConfig": {
          "number": {
            "prefix": ""
          }
        },
        "formattedStatics": ">statics | formatByType(formattedConfig)",
        "statics": [
          ["All"],
          ["*"]
        ],
        "label": ">primary | seriesByName(\"model\") | renameSeries(\"label\") | formatByType(formattedConfig)",
        "value": ">primary | seriesByName(\"model\") | renameSeries(\"value\") | formatByType(formattedConfig)"
      }
    }
  },
  "dataSources": {
    "ds_model_options": {
      "type": "ds.search",
      "options": {
        "query": "`claude_metric_events` | stats count by model | sort - count | fields model"
      },
      "name": "Model Options"
    },
    "ds_base_time": {
      "type": "ds.search",
      "options": {
        "query": "`claude_metric_events` | search model=$model_tok|s$ | eval cache_savings_usd=cache_read_tokens*(input_cost_per_mtok-cache_read_cost_per_mtok)/1000000 | timechart sum(input_tokens) as input_tokens, sum(cache_read_tokens) as cache_read_tokens, sum(cache_creation_tokens) as cache_creation_tokens, sum(cache_savings_usd) as cache_savings_usd"
      },
      "name": "Base: Cache Over Time"
    },
    "ds_kpi_hit_pct": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_time",
        "query": "| stats sum(input_tokens) as i, sum(cache_read_tokens) as cr, sum(cache_creation_tokens) as cc | eval count=if(i+cr+cc>0, round(cr/(i+cr+cc)*100,1).\"%\", \"n/a\") | fields count"
      },
      "name": "KPI Cache Hit %"
    },
    "ds_kpi_reads": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_time",
        "query": "| stats sum(cache_read_tokens) as count | eval count=tostring(count,\"commas\") | fields count"
      },
      "name": "KPI Cache Reads"
    },
    "ds_kpi_creates": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_time",
        "query": "| stats sum(cache_creation_tokens) as count | eval count=tostring(count,\"commas\") | fields count"
      },
      "name": "KPI Cache Creates"
    },
    "ds_kpi_savings": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_time",
        "query": "| stats sum(cache_savings_usd) as count | eval count=\"$\".tostring(round(count,2),\"commas\") | fields count"
      },
      "name": "KPI Est. Savings"
    },
    "ds_hit_time": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_time",
        "query": "| eval \"Cache Hit %\"=if(input_tokens+cache_read_tokens+cache_creation_tokens>0, round(cache_read_tokens/(input_tokens+cache_read_tokens+cache_creation_tokens)*100,1), null()) | fields _time, \"Cache Hit %\""
      },
      "name": "Cache Hit % Over Time"
    },
    "ds_rw_time": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_time",
        "query": "| fields _time, cache_read_tokens, cache_creation_tokens | rename cache_read_tokens as \"Cache Read\", cache_creation_tokens as \"Cache Created\""
      },
      "name": "Cache Read vs Created"
    },
    "ds_savings_time": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_time",
        "query": "| fields _time, cache_savings_usd | rename cache_savings_usd as \"Est. Savings (USD)\""
      },
      "name": "Est. Savings Over Time"
    },
    "ds_base_model": {
      "type": "ds.search",
      "options": {
        "query": "`claude_metric_events` | search model=$model_tok|s$ | stats sum(input_tokens) as input, sum(cache_read_tokens) as cache_read, sum(cache_creation_tokens) as cache_created by model"
      },
      "name": "Base: Cache by Model"
    },
    "ds_model_hit": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_model",
        "query": "| eval \"Cache Hit %\"=if(input+cache_read+cache_created>0, round(cache_read/(input+cache_read+cache_created)*100,1), 0) | sort - \"Cache Hit %\" | fields model, \"Cache Hit %\" | rename model as \"Model\""
      },
      "name": "Cache Hit % by Model"
    },
    "ds_base_session": {
      "type": "ds.search",
      "options": {
        "query": "`claude_metric_events` | search model=$model_tok|s$ | stats sum(input_tokens) as input, sum(cache_read_tokens) as cache_read, sum(cache_creation_tokens) as cache_created, sum(cost_usd) as cost by sessionId"
      },
      "name": "Base: Cache by Session"
    },
    "ds_session_cache": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_session",
        "query": "| eval \"Cache Hit %\"=if(input+cache_read+cache_created>0, round(cache_read/(input+cache_read+cache_created)*100,1), 0), cost=round(cost,4) | sort - cache_read | head 25 | rename sessionId as \"Session ID\", input as \"Input\", cache_read as \"Cache Read\", cache_created as \"Cache Created\", cost as \"Cost (USD)\""
      },
      "name": "Sessions by Cache Performance"
    }
  },
  "visualizations": {
    "viz_kpi_hit_pct": {
      "type": "splunk.singlevalue",
      "title": "Cache Hit %",
      "dataSources": {
        "primary": "ds_kpi_hit_pct"
      },
      "options": {
        "majorValue": "> primary | seriesByIndex(0)"
      }
    },
    "viz_kpi_reads": {
      "type": "splunk.singlevalue",
      "title": "Cache Reads",
      "dataSources": {
        "primary": "ds_kpi_reads"
      },
      "options": {
        "majorValue": "> primary | seriesByIndex(0)"
      }
    },
    "viz_kpi_creates": {
      "type": "splunk.singlevalue",
      "title": "Cache Creates",
      "dataSources": {
        "primary": "ds_kpi_creates"
      },
      "options": {
        "majorValue": "> primary | seriesByIndex(0)"
      }
    },
    "viz_kpi_savings": {
      "type": "splunk.singlevalue",
      "title": "Est. Savings",
      "dataSources": {
        "primary": "ds_kpi_savings"
      },
      "options": {
        "majorValue": "> primary | seriesByIndex(0)"
      }
    },
    "viz_hit_time": {
      "type": "splunk.line",
      "title": "Cache Hit % Over Time",
      "dataSources": {
        "primary": "ds_hit_time"
      },
      "options": {}
    },
    "viz_rw_time": {
      "type": "splunk.area",
      "title": "Cache Read vs Created",
      "dataSources": {
        "primary": "ds_rw_time"
      },
      "options": {
        "stackMode": "stacked"
      }
    },
    "viz_savings_time": {
      "type": "splunk.line",
      "title": "Est. Savings Over Time",
      "dataSources": {
        "primary": "ds_savings_time"
      },
      "options": {}
    },
    "viz_model_hit": {
      "type": "splunk.bar",
      "title": "Cache Hit % by Model",
      "dataSources": {
        "primary": "ds_model_hit"
      },
      "options": {}
    },
    "viz_session_table": {
      "type": "splunk.table",
      "title": "Sessions by Cache Performance",
      "dataSources": {
        "primary": "ds_session_cache"
      },
      "options": {},
      "eventHandlers": [
        {
          "type": "drilldown.linkToDashboard",
          "options": {
            "app": "VisiCore_App_for_AI_Observability",
            "dashboard": "sessions",
            "tokens": [
              {
                "token": "form.session_tok",
                "value": "row.Session ID.value"
              }
            ]
          }
        }
      ]
    }
  },
  "layout": {
    "type": "grid",
    "options": {},
    "structure": [
      {"item": "viz_kpi_hit_pct", "type": "block", "position": {"x": 0, "y": 0, "w": 300, "h": 120}},
      {"item": "viz_kpi_reads", "type": "block", "position": {"x": 300, "y": 0, "w": 300, "h": 120}},
      {"item": "viz_kpi_creates", "type": "block", "position": {"x": 600, "y": 0, "w": 300, "h": 120}},
      {"item": "viz_kpi_savings", "type": "block", "position": {"x": 900, "y": 0, "w": 300, "h": 120}},
      {"item": "viz_hit_time", "type": "block", "position": {"x": 0, "y": 120, "w": 600, "h": 300}},
      {"item": "viz_rw_time", "type": "block", "position": {"x": 600, "y": 120, "w": 600, "h": 300}},
      {"item": "viz_savings_time", "type": "block", "position": {"x": 0, "y": 420, "w": 600, "h": 300}},
      {"item": "viz_model_hit", "type": "block", "position": {"x": 600, "y": 420, "w": 600, "h": 300}},
      {"item": "viz_session_table", "type": "block", "position": {"x": 0, "y": 720, "w": 1200, "h": 320}}
    ],
    "globalInputs": ["input_timerange", "input_model"]
  }
}
